class Solution {
public:
    std::vector<int> findAllGoodIndices(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> left(n, 1);
        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) left[i] = left[i - 1] + 1;
        }
        std::vector<int> right(n, 1);
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] <= nums[i + 1]) right[i] = right[i + 1] + 1;
        }
        std::vector<int> res;
        for (int i = k; i < n - k; i++) {
            if (left[i - 1] >= k && right[i + 1] >= k) res.push_back(i);
        }
        return res;
    }
};

class Solution {
    public java.util.List<Integer> findAllGoodIndices(int[] nums, int k) {
        int n = nums.length;
        int[] left = new int[n];
        java.util.Arrays.fill(left, 1);
        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) left[i] = left[i - 1] + 1;
        }
        int[] right = new int[n];
        java.util.Arrays.fill(right, 1);
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] <= nums[i + 1]) right[i] = right[i + 1] + 1;
        }
        java.util.List<Integer> res = new java.util.ArrayList<>();
        for (int i = k; i < n - k; i++) {
            if (left[i - 1] >= k && right[i + 1] >= k) res.add(i);
        }
        return res;
    }
}

